# Add chat functions before authMode
needle='function authMode(reg)'
chatjs=r'''function chatText(data){return data?.text||data?.content||data?.message||data?.result?.text||data?.result?.content||data?.choices?.[0]?.message?.content||pretty(data)}
function addMessage(role,text,typing=false){$('#chatWelcome')?.remove();const wrap=document.createElement('div');wrap.className='msg '+role;wrap.innerHTML=`<div class="msg-avatar">${role==='user'?'U':'◈'}</div><div class="bubble">${typing?'<div class="typing"><i></i><i></i><i></i></div>':esc(text)}</div>`;$('#chatMessages').appendChild(wrap);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;return wrap}
async function loadChatModels(){if($('#chatModel').options.length===1){const d=await api('/api/models?capability=chat');const list=(d.models||[]).filter(m=>m.configured||m.free);$('#chatModel').innerHTML='<option value="">Best available model</option>'+list.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join('')}if(!state.chatLoaded){state.chatLoaded=true;try{state.chat=JSON.parse(localStorage.getItem('bg_chat')||'[]')}catch{state.chat=[]}if(state.chat.length){state.chat.forEach(m=>addMessage(m.role==='user'?'user':'ai',m.content))}}}
async function sendChat(text){text=String(text||'').trim();if(!text)return;state.chat=state.chat||[];addMessage('user',text);state.chat.push({role:'user',content:text});$('#chatInput').value='';const wait=addMessage('ai','',true),btn=$('#chatSend');busy(btn,true);try{const d=await api('/api/generate/chat',{method:'POST',body:JSON.stringify({model:$('#chatModel').value,messages:state.chat,prompt:text})});const answer=chatText(d);wait.querySelector('.bubble').textContent=answer;state.chat.push({role:'assistant',content:answer});localStorage.setItem('bg_chat',JSON.stringify(state.chat.slice(-20)))}catch(e){wait.querySelector('.bubble').textContent='Error: '+e.message;toast(e.message,true)}finally{busy(btn,false);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}}
'''
if needle not in s: raise SystemExit('JS target missing')
s=s.replace(needle,chatjs+needle)
# Add interactions before hash listener
needle2="window.addEventListener('hashchange'"
events=r'''$('#chatForm').onsubmit=e=>{e.preventDefault();sendChat($('#chatInput').value)};$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chatForm').requestSubmit()}};$$('.suggestion').forEach(b=>b.onclick=()=>sendChat(b.textContent));$('#clearChat').onclick=()=>{state.chat=[];localStorage.removeItem('bg_chat');$('#chatMessages').innerHTML='<div id="chatWelcome" class="chat-welcome"><div class="ai-glyph">◈</div><h1>New conversation</h1><p>What would you like to create?</p></div>'};
const motionLite=localStorage.getItem('bg_motion')==='lite';document.body.classList.toggle('motion-lite',motionLite);$('#motionToggle').onclick=()=>{document.body.classList.toggle('motion-lite');localStorage.setItem('bg_motion',document.body.classList.contains('motion-lite')?'lite':'full');toast(document.body.classList.contains('motion-lite')?'Animations reduced':'Full animation enabled')};
document.addEventListener('pointermove',e=>{if(document.body.classList.contains('motion-lite')||innerWidth<800)return;const x=(e.clientX/innerWidth-.5)*4,y=(e.clientY/innerHeight-.5)*-4;document.querySelectorAll('.feature').forEach(c=>c.style.transform=`perspective(900px) rotateY(${x}deg) rotateX(${y}deg)`)},{passive:true});
'''
s=s.replace(needle2,events+needle2)
